// src/api/buyerCustomerAPI.js
import axios_api from "./axios";
import { apiPath } from "./config";

const host = apiPath("/buyer/buyercustomer");

// 전체 조회
export const getBuyerCustomer = async () => {
  const res = await axios_api.get(host);
  return res.data;
};

// 등록
export const createBuyerCustomer = async (formData) => {
  const payload = {
    buyerComp: String(formData.buyerComp || "").trim(),
    buyerName: String(formData.buyerName || "").trim(),
    buyerEmail: String(formData.buyerEmail || "").trim(),
    buyerPhone: String(formData.buyerPhone || "").trim(),
    buyerAddr: String(formData.buyerAddr || "").trim(),
  };
  const res = await axios_api.post(host, payload);
  return res.data;
};

// 수정
export const updateBuyerCustomer = async (buyerNo, formData) => {
  if (buyerNo == null) throw new Error("buyerNo 누락");
  const payload = {
    buyerComp: String(formData.buyerComp || "").trim(),
    buyerName: String(formData.buyerName || "").trim(),
    buyerEmail: String(formData.buyerEmail || "").trim(),
    buyerPhone: String(formData.buyerPhone || "").trim(),
    buyerAddr: String(formData.buyerAddr || "").trim(),
  };
  const res = await axios_api.put(apiPath(`/buyer/buyercustomer/${buyerNo}`), payload);
  return res.data;
};

// 삭제
export const deleteBuyerCustomer = async (buyerNo) => {
  if (buyerNo == null) throw new Error("buyerNo 누락");
  const res = await axios_api.delete(apiPath(`/buyer/buyercustomer/${buyerNo}`));
  return res.data;
};
